#!/usr/bin/env node

/**
 * @dock-tech/shared-copilot-front-lib init
 *
 * Bootstrap script que configura um projeto Vue com todas as instructions,
 * prompts, agents e validação do Design System.
 *
 * Uso: npx shared-copilot-front-lib [--template landing-page|console-app]
 */

import { existsSync, mkdirSync, cpSync, readFileSync, writeFileSync, readdirSync } from 'fs';
import { join, resolve } from 'path';
import { fileURLToPath } from 'url';

const __dirname = fileURLToPath(new URL('.', import.meta.url));
const ROOT = resolve(__dirname, '..');
const CWD = process.cwd();

const TEMPLATE = process.argv.includes('--template')
  ? process.argv[process.argv.indexOf('--template') + 1] || 'project-init'
  : 'project-init';

const VALID_TEMPLATES = ['project-init', 'landing-page', 'console-app'];
if (!VALID_TEMPLATES.includes(TEMPLATE)) {
  console.error(`❌ Template inválido: "${TEMPLATE}". Use: ${VALID_TEMPLATES.join(', ')}`);
  process.exit(1);
}

const COLORS = {
  reset: '\x1b[0m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  cyan: '\x1b[36m',
  red: '\x1b[31m',
};

function log(msg, color = 'reset') {
  console.log(`${COLORS[color]}${msg}${COLORS.reset}`);
}

function ensureDir(dir) {
  if (!existsSync(dir)) {
    mkdirSync(dir, { recursive: true });
  }
}

function copyIfNotExists(src, dest, label) {
  if (existsSync(dest)) {
    log(`  ⚠️  ${label} já existe — pulando (use --force para sobrescrever)`, 'yellow');
    return false;
  }
  cpSync(src, dest, { recursive: true });
  log(`  ✅ ${label}`, 'green');
  return true;
}

function main() {
  log('\n🚀 @dock-tech/shared-copilot-front-lib init\n', 'cyan');
  log(`Template: ${TEMPLATE}`, 'cyan');
  log(`Destino: ${CWD}\n`, 'cyan');

  // 1. Criar .github/ structure
  const githubDir = join(CWD, '.github');
  ensureDir(join(githubDir, 'instructions'));
  ensureDir(join(githubDir, 'prompts'));
  ensureDir(join(githubDir, 'agents'));

  // 2. Copiar instructions do copilot-config (formato scoped — coexiste com DS e outros pacotes)
  // Usa instructions/ em vez de copilot-instructions.md para não conflitar com
  // shared-design-system-vue-lib (que escreve instructions/design-system.instructions.md).
  // GitHub Copilot lê TODOS os *.instructions.md em .github/instructions/ automaticamente.
  log('📋 Configurando instructions...', 'cyan');
  copyIfNotExists(
    join(ROOT, 'base', 'copilot-instructions.md'),
    join(githubDir, 'instructions', 'copilot-config.instructions.md'),
    '.github/instructions/copilot-config.instructions.md'
  );

  // 3. Copiar instructions scoped — todas as disponíveis em base/instructions/
  const instructionsDir = join(ROOT, 'base', 'instructions');
  const files = readdirSync(instructionsDir).filter(f => f.endsWith('.instructions.md')).sort();
  for (const file of files) {
    copyIfNotExists(
      join(instructionsDir, file),
      join(githubDir, 'instructions', file),
      `.github/instructions/${file}`
    );
  }

  // 4. Copiar prompts — todos os disponíveis em base/prompts/
  log('\n📝 Configurando prompts...', 'cyan');
  const promptsDir = join(ROOT, 'base', 'prompts');
  const prompts = readdirSync(promptsDir).filter(f => f.endsWith('.prompt.md')).sort();
  ensureDir(join(githubDir, 'prompts'));
  for (const file of prompts) {
    copyIfNotExists(
      join(promptsDir, file),
      join(githubDir, 'prompts', file),
      `.github/prompts/${file}`
    );
  }

  // 4b. Copiar skills — todos os disponíveis em base/skills/
  log('\n🔧 Configurando skills...', 'cyan');
  const skillsBaseDir = join(ROOT, 'base', 'skills');
  if (existsSync(skillsBaseDir)) {
    const skills = readdirSync(skillsBaseDir);
    ensureDir(join(githubDir, 'skills'));
    for (const skill of skills) {
      const srcSkillDir = join(skillsBaseDir, skill);
      const destSkillDir = join(githubDir, 'skills', skill);
      ensureDir(destSkillDir);
      const skillFiles = readdirSync(srcSkillDir).filter(f => f.endsWith('.md'));
      for (const file of skillFiles) {
        copyIfNotExists(
          join(srcSkillDir, file),
          join(destSkillDir, file),
          `.github/skills/${skill}/${file}`
        );
      }
    }
  }

  // 5. Copiar agents
  log('\n🤖 Configurando agents...', 'cyan');
  const agentsDir = join(ROOT, 'base', 'agents');
  const agents = [
    'design-reviewer.agent.md',
    'a11y-auditor.agent.md',
    'ds-gatekeeper.agent.md',
    'security-auditor.agent.md',
  ];
  for (const file of agents) {
    copyIfNotExists(
      join(agentsDir, file),
      join(githubDir, 'agents', file),
      `.github/agents/${file}`
    );
  }

  // 6. Copiar dock-ds.config.json (template)
  log('\n⚙️  Configurando dock-ds.config.json...', 'cyan');
  const templateDir = join(ROOT, 'templates', TEMPLATE);
  copyIfNotExists(
    join(templateDir, 'dock-ds.config.json'),
    join(CWD, 'dock-ds.config.json'),
    'dock-ds.config.json'
  );

  // 6b. Copiar dock.yaml (pipeline CI/CD padrão Dock)
  log('\n🔄 Configurando dock.yaml (pipeline CI/CD)...', 'cyan');
  copyIfNotExists(
    join(templateDir, 'dock.yaml'),
    join(CWD, 'dock.yaml'),
    'dock.yaml'
  );

  // 6b2. Copiar eslint.config.js (flat config com governance rules)
  log('\n🔒 Configurando eslint.config.js (governance enforcement)...', 'cyan');
  const eslintConfigSrc = join(templateDir, 'eslint.config.js');
  if (existsSync(eslintConfigSrc)) {
    copyIfNotExists(
      eslintConfigSrc,
      join(CWD, 'eslint.config.js'),
      'eslint.config.js (flat config + dock-ds rules)'
    );
  }

  // 6c. Copiar instructions específicas do template (se existirem)
  const templateInstructionsDir = join(templateDir, 'instructions');
  if (existsSync(templateInstructionsDir)) {
    log('\n📐 Configurando instructions do template...', 'cyan');
    const templateInstructions = readdirSync(templateInstructionsDir).filter(f => f.endsWith('.md'));
    for (const file of templateInstructions) {
      copyIfNotExists(
        join(templateInstructionsDir, file),
        join(githubDir, 'instructions', file),
        `.github/instructions/${file}`
      );
    }
  }

  // 7. Adicionar scripts no package.json (se existe)
  const pkgPath = join(CWD, 'package.json');
  if (existsSync(pkgPath)) {
    log('\n📦 Atualizando package.json scripts...', 'cyan');
    try {
      const pkg = JSON.parse(readFileSync(pkgPath, 'utf-8'));
      const newScripts = {
        'validate:design': 'node node_modules/@dock-tech/shared-copilot-front-lib/copilot-config/scripts/validate-design.mjs',
        'validate:contrast': 'node node_modules/@dock-tech/shared-copilot-front-lib/copilot-config/scripts/validate-contrast.mjs',
        'validate:states': 'node node_modules/@dock-tech/shared-copilot-front-lib/copilot-config/scripts/check-component-states.mjs',
        'validate': 'node node_modules/@dock-tech/shared-copilot-front-lib/copilot-config/scripts/validate-pipeline.mjs',
        'validate:figma': 'node node_modules/@dock-tech/shared-copilot-front-lib/copilot-config/scripts/figma-fidelity-audit.mjs',
        'validate:config': 'node node_modules/@dock-tech/shared-copilot-front-lib/copilot-config/scripts/validate-config.mjs',
        'compliance': 'node node_modules/@dock-tech/shared-copilot-front-lib/copilot-config/scripts/compliance-report.mjs',
        'lint:dock-ds': 'ESLINT_USE_FLAT_CONFIG=true eslint .',
        'lint:dock-ds:fix': 'ESLINT_USE_FLAT_CONFIG=true eslint . --fix',
      };

      let added = 0;
      for (const [key, value] of Object.entries(newScripts)) {
        if (!pkg.scripts?.[key]) {
          pkg.scripts = pkg.scripts || {};
          pkg.scripts[key] = value;
          added++;
        }
      }

      if (added > 0) {
        writeFileSync(pkgPath, JSON.stringify(pkg, null, 2) + '\n');
        log(`  ✅ ${added} scripts adicionados ao package.json`, 'green');
      } else {
        log('  ⚠️  Scripts já existem no package.json', 'yellow');
      }
    } catch (e) {
      log(`  ❌ Erro ao atualizar package.json: ${e.message}`, 'red');
    }
  }

  // 8. Copiar PR template
  log('\n📋 Configurando PR template...', 'cyan');
  const prTemplateSrc = join(templateDir, '.github', 'pull_request_template.md');
  if (existsSync(prTemplateSrc)) {
    copyIfNotExists(
      prTemplateSrc,
      join(githubDir, 'pull_request_template.md'),
      '.github/pull_request_template.md'
    );
  }

  // 9. Automação de gate — pre-commit (husky + lint-staged) e workflow de CI
  log('\n🔒 Configurando gate automático (pre-commit + CI)...', 'cyan');
  const huskySrc = join(templateDir, '.husky', 'pre-commit');
  if (existsSync(huskySrc)) {
    ensureDir(join(CWD, '.husky'));
    copyIfNotExists(huskySrc, join(CWD, '.husky', 'pre-commit'), '.husky/pre-commit');
  }
  const lintStagedSrc = join(templateDir, 'lint-staged.config.mjs');
  if (existsSync(lintStagedSrc)) {
    copyIfNotExists(lintStagedSrc, join(CWD, 'lint-staged.config.mjs'), 'lint-staged.config.mjs');
  }
  const workflowSrc = join(templateDir, '.github', 'workflows', 'frontend-quality.yml');
  if (existsSync(workflowSrc)) {
    ensureDir(join(githubDir, 'workflows'));
    copyIfNotExists(
      workflowSrc,
      join(githubDir, 'workflows', 'frontend-quality.yml'),
      '.github/workflows/frontend-quality.yml'
    );
  }

  // Done
  log('\n✨ Setup completo!\n', 'green');
  log('Próximos passos:', 'cyan');
  log('  1. Edite dock-ds.config.json com os tokens do seu projeto');
  log('  2. Configure ESLint com: import dockDs from "@dock-tech/shared-copilot-front-lib/eslint-plugin"');
  log('  3. Instale o gate de pre-commit: npm i -D husky lint-staged && npx husky init');
  log('  4. Rode: npm run validate && npm run validate:contrast');
  log('  5. Se houver Figma, rode: npm run validate:figma');
  log('  6. Comece a usar os prompts: /nova-tela, /novo-componente, etc.');
  log('');
}

main();
